-- Generated by NCWE Studio from the world project "NCM Race Week Day 1".
-- The package is preloaded as the required mod "ncm_race_week_map-assets": the launcher installs it
-- before Cyberpunk starts. Changing it needs a dedicated-server restart, then a fresh game launch.
resource "ncm_race_week_map"
version "1.0.1"
auto_start true

-- No `dependency "archivexl"`: OPEN//77 resolves dependency names as RESOURCES, and that line aborted the whole
-- automatic start on Online (2026-10-08, L351). ArchiveXL 1.27.1 is a declared required mod of the server.
preload_mod "dist/ncm-race-week-map.zip"

server_script "server/main.lua"
